import React, { useEffect, useState } from 'react';
import { useLocation, useParams, useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { tours } from '../data/mockData';
import SafeIcon from '../common/SafeIcon';
import { getStorageKey, safeRead, safeWrite } from '../utils/localEvents';
import { getDisplayTourDescription, getDisplayTourTitle, getPreviewMode, withPreviewMode } from '../utils/previewMode';

const iconForMode = {
  driving: 'Navigation',
  walking: 'MapPin',
  transit: 'Truck',
  'audio-ar': 'Radio'
};

function getTourState(tour) {
  const stops = tour.stops || [];
  const visitedStops = safeRead(getStorageKey('progress', tour.id), []);
  const savedStops = safeRead(getStorageKey('saved-stops', tour.id), []);
  const activatedOffers = safeRead(getStorageKey('offers', tour.id), []);
  const loyaltyStamps = safeRead(getStorageKey('loyalty', tour.id), {});
  const savedIndex = Number(localStorage.getItem(getStorageKey('current-stop-index', tour.id)));
  const firstUnvisitedIndex = stops.findIndex(stop => !visitedStops.includes(stop.id));
  const resumeIndex = Number.isInteger(savedIndex) && savedIndex >= 0 && savedIndex < stops.length
    ? savedIndex
    : firstUnvisitedIndex >= 0 ? firstUnvisitedIndex : 0;

  return {
    visitedStops,
    savedStops,
    activatedOffers,
    loyaltyStampCount: Object.values(loyaltyStamps).reduce((sum, count) => sum + Number(count || 0), 0),
    resumeIndex,
    resumeStop: stops[resumeIndex],
    resumePosition: resumeIndex + 1,
    progressPercent: stops.length ? Math.round((visitedStops.length / stops.length) * 100) : 0
  };
}

export default function TourDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const location = useLocation();
  const tour = tours.find(t => t.id === id) || tours[0];
  const previewMode = getPreviewMode(location.search);
  const reviewerMode = previewMode === 'reviewer';
  const displayTitle = getDisplayTourTitle(tour, previewMode);
  const displayDescription = getDisplayTourDescription(tour, previewMode);
  const [showModes, setShowModes] = useState(false);
  const [offlineStatus, setOfflineStatus] = useState('');
  const [offlineSavedAt, setOfflineSavedAt] = useState('');
  const [tourState, setTourState] = useState(() => getTourState(tour));

  useEffect(() => {
    setTourState(getTourState(tour));
    const savedPack = safeRead(`tour-engine:offline-pack:${tour.id}`, null);
    setOfflineSavedAt(savedPack ? savedPack.savedAt || 'saved' : '');
  }, [tour.id]);

  useEffect(() => {
    const refreshState = () => setTourState(getTourState(tour));
    window.addEventListener('focus', refreshState);
    window.addEventListener('storage', refreshState);
    return () => {
      window.removeEventListener('focus', refreshState);
      window.removeEventListener('storage', refreshState);
    };
  }, [tour]);

  const previewStops = () => {
    navigate(withPreviewMode(`/player/${tour.id}`, location.search));
  };

  const saveOfflinePack = () => {
    const offlinePack = {
      savedAt: new Date().toISOString(),
      tourId: tour.id,
      packId: tour.packId,
      title: tour.title,
      stops: tour.stops?.map(stop => ({ id: stop.id, title: stop.title, coordinates: stop.coordinates })) || []
    };
    safeWrite(`tour-engine:offline-pack:${tour.id}`, offlinePack);
    setOfflineSavedAt(offlinePack.savedAt);
    setOfflineStatus('Saved on this device');
    window.setTimeout(() => setOfflineStatus(''), 2500);
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      className="bg-[#FDFBF7] min-h-screen pb-32"
    >
      <div className="relative h-72 overflow-hidden bg-gradient-to-br from-slate-900 via-orange-900 to-amber-600">
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_20%_25%,rgba(255,255,255,.24),transparent_24%),radial-gradient(circle_at_80%_10%,rgba(255,255,255,.16),transparent_28%)]" />
        <svg className="absolute inset-0 w-full h-full opacity-80" viewBox="0 0 100 100" preserveAspectRatio="none">
          <path d="M 12 78 C 26 48, 42 62, 55 36 S 78 42, 90 18" fill="none" stroke="rgba(255,255,255,.75)" strokeWidth="2.5" strokeLinecap="round" strokeDasharray="4 4" />
          {[12, 32, 55, 76, 90].map((x, i) => <circle key={x} cx={x} cy={[78, 56, 36, 42, 18][i]} r="4" fill="white" stroke="#c2410c" strokeWidth="1.5" />)}
        </svg>
        <div className="absolute left-5 top-5 rounded-full bg-white/15 px-3 py-1 text-xs font-bold text-white backdrop-blur">No app install required</div>
        <div className="absolute inset-0 bg-gradient-to-t from-[#FDFBF7] via-transparent to-black/20" />
      </div>

      <div className="px-5 -mt-10 relative z-10">
        <div className="bg-white rounded-3xl p-6 shadow-md border border-slate-100">
          <div className="flex items-center gap-2 mb-3 flex-wrap">
            <span className="bg-orange-100 text-orange-800 text-[10px] font-bold uppercase tracking-wider px-2 py-1 rounded">
              {tour.subtitle}
            </span>
            {reviewerMode && <span className="bg-slate-100 text-slate-700 text-[10px] font-bold uppercase tracking-wider px-2 py-1 rounded">
              {tour.packId}
            </span>}
            <span className="text-xs text-slate-500 font-medium">{tour.city}</span>
          </div>

          <h1 className="text-3xl font-bold text-slate-900 mb-2" style={{ fontFamily: 'Georgia, serif' }}>
            {displayTitle}
          </h1>

          <p className="text-sm font-medium text-slate-600 mb-6 flex items-center gap-2">
            <SafeIcon name="Map" className="w-4 h-4" />
            {tour.stats || 'Structured tour pack · preview mode'}
          </p>

          <p className="text-sm text-slate-600 leading-relaxed">{displayDescription || 'This sample pack is waiting for route and stop normalization.'}</p>

        <div className="mt-6 grid grid-cols-2 gap-3">
            <div className="rounded-xl border border-emerald-100 bg-emerald-50 p-3">
              <p className="text-[10px] font-bold uppercase tracking-widest text-emerald-800">PWA status</p>
              <p className="text-sm font-bold text-emerald-950">Save offline</p>
            </div>
            <div className="rounded-xl border border-amber-100 bg-amber-50 p-3">
              <p className="text-[10px] font-bold uppercase tracking-widest text-amber-800">Publishing</p>
              <p className="text-sm font-bold text-amber-950">{reviewerMode ? tour.status || 'Draft pack' : 'Preview pack'}</p>
            </div>
          </div>

          <div className="mt-5 flex items-start gap-2 bg-slate-50 p-3 rounded-xl border border-slate-100">
            <SafeIcon name="Shield" className="w-5 h-5 text-slate-600 flex-shrink-0" />
            <p className="text-xs text-slate-600">
              {reviewerMode ? 'Coordinates, safety, and media rights must be reviewed before marketplace publishing or proximity-triggered audio AR.' : 'Check current hours, route conditions, and surroundings before you go.'}
            </p>
          </div>
        </div>

        {tour.stops?.length > 0 && (
          <div className="mt-5 rounded-3xl border border-blue-100 bg-blue-50 p-4 shadow-sm">
            <div className="flex items-start justify-between gap-3">
              <div>
                <p className="text-[10px] font-bold uppercase tracking-widest text-blue-700">{reviewerMode ? 'Field-test progress' : 'Your progress'}</p>
                <h2 className="mt-1 text-lg font-black text-slate-900">
                  {tourState.resumeStop ? `Resume at stop ${tourState.resumePosition}` : 'Ready to start'}
                </h2>
                <p className="mt-1 text-xs leading-relaxed text-blue-950/75">
                  {tourState.resumeStop?.title || 'No stop state has been saved yet.'}
                </p>
              </div>
              <span className="rounded-full bg-white px-2 py-1 text-[10px] font-bold uppercase text-blue-700">
                {tourState.progressPercent}% walked
              </span>
            </div>

            <div className="mt-4 h-2 overflow-hidden rounded-full bg-white">
              <div className="h-full rounded-full bg-blue-700 transition-all" style={{ width: `${tourState.progressPercent}%` }} />
            </div>

            <div className="mt-4 grid grid-cols-4 gap-2 text-center">
              <div className="rounded-2xl bg-white p-2">
                <p className="text-base font-black text-slate-900">{tourState.visitedStops.length}</p>
                <p className="text-[9px] font-bold uppercase tracking-widest text-slate-400">visited</p>
              </div>
              <div className="rounded-2xl bg-white p-2">
                <p className="text-base font-black text-slate-900">{tourState.savedStops.length}</p>
                <p className="text-[9px] font-bold uppercase tracking-widest text-slate-400">saved</p>
              </div>
              <div className="rounded-2xl bg-white p-2">
                <p className="text-base font-black text-slate-900">{tourState.activatedOffers.length}</p>
                <p className="text-[9px] font-bold uppercase tracking-widest text-slate-400">{reviewerMode ? 'offers' : 'ideas'}</p>
              </div>
              <div className="rounded-2xl bg-white p-2">
                <p className="text-base font-black text-slate-900">{tourState.loyaltyStampCount}</p>
                <p className="text-[9px] font-bold uppercase tracking-widest text-slate-400">{reviewerMode ? 'stamps' : 'visits'}</p>
              </div>
            </div>
          </div>
        )}

        {offlineSavedAt && (
          <div className="mt-5 rounded-2xl border border-emerald-100 bg-emerald-50 p-3 text-xs text-emerald-800">
            <p className="font-bold uppercase tracking-widest">Offline pack saved</p>
            <p className="mt-1">{reviewerMode ? 'This device has the compact field-test pack cached. Service worker/app shell still controls full offline behavior.' : 'This tour is saved on this device for easier access while you are out.'}</p>
          </div>
        )}

        <div className="mt-6 grid grid-cols-2 gap-3">
          <button onClick={previewStops} className="flex items-center justify-center gap-2 bg-white border border-slate-200 text-slate-700 py-3 rounded-xl font-semibold shadow-sm hover:bg-slate-50 active:scale-95">
            <SafeIcon name="List" className="w-4 h-4" />
            {tourState.visitedStops.length ? 'Resume Tour' : 'Preview Stops'}
          </button>
          <div className="relative">
            <button onClick={saveOfflinePack} className={`flex w-full items-center justify-center gap-2 border py-3 rounded-xl font-semibold shadow-sm hover:bg-slate-50 active:scale-95 ${offlineSavedAt ? 'bg-emerald-50 border-emerald-100 text-emerald-700' : 'bg-white border-slate-200 text-slate-700'}`}>
              <SafeIcon name={offlineSavedAt ? 'Check' : 'Download'} className="w-4 h-4" />
              {offlineSavedAt ? 'Offline Saved' : 'Save Offline'}
            </button>
            {offlineStatus && (
              <span className="absolute left-1/2 top-12 -translate-x-1/2 whitespace-nowrap rounded-full bg-slate-900 px-2 py-1 text-[10px] font-bold text-white shadow">
                {offlineStatus}
              </span>
            )}
          </div>
        </div>
      </div>

      <div className="fixed bottom-0 left-0 right-0 p-5 bg-gradient-to-t from-[#FDFBF7] via-[#FDFBF7] to-transparent z-40 max-w-md mx-auto">
        <button
          onClick={() => setShowModes(true)}
          className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold text-lg shadow-lg flex items-center justify-center gap-2 active:scale-95 transition-transform"
        >
          <SafeIcon name="Navigation" className="w-5 h-5" />
          Choose Route Mode
        </button>
      </div>

      <AnimatePresence>
        {showModes && (
          <>
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setShowModes(false)}
              className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-50 max-w-md mx-auto"
            />
            <motion.div
              initial={{ y: '100%' }}
              animate={{ y: 0 }}
              exit={{ y: '100%' }}
              transition={{ type: 'spring', damping: 25, stiffness: 200 }}
              className="fixed bottom-0 left-0 right-0 bg-white rounded-t-3xl z-50 p-6 max-w-md mx-auto shadow-2xl pb-safe"
            >
              <div className="w-12 h-1.5 bg-slate-200 rounded-full mx-auto mb-6" />
              <h3 className="text-xl font-bold text-slate-900 mb-1" style={{ fontFamily: 'Georgia, serif' }}>Select route mode</h3>
              <p className="text-xs text-slate-500 mb-4">Manual-first PWA player now. Native app later only if audio AR/proximity needs it.</p>

              <div className="space-y-3 mb-6">
                {(tour.routeModes || []).map((mode, index) => {
                  const isPlayable = index === 0 || mode.recommended;
                  return (
                  <button
                    key={mode.id}
                    onClick={() => isPlayable && navigate(withPreviewMode(`/player/${tour.id}`, location.search))}
                    disabled={!isPlayable}
                    className={`w-full flex items-center gap-4 p-4 rounded-2xl text-left transition-colors ${mode.recommended ? 'border-2 border-orange-500 bg-orange-50/50' : 'border border-slate-200 bg-white'} ${!isPlayable ? 'opacity-60 cursor-not-allowed' : ''}`}
                  >
                    <div className="w-12 h-12 rounded-full bg-slate-100 flex items-center justify-center flex-shrink-0">
                      <SafeIcon name={iconForMode[mode.id] || 'Map'} className={`w-6 h-6 ${mode.recommended ? 'text-orange-600' : 'text-slate-600'}`} />
                    </div>
                    <div>
                      <h4 className="font-bold text-slate-900">{mode.label}</h4>
                      <p className="text-xs text-slate-500 mt-0.5">{mode.meta}</p>
                    </div>
                    {index === 0 && <SafeIcon name="ChevronRight" className="w-5 h-5 text-orange-500 ml-auto" />}
                  </button>
                  );
                })}
              </div>
            </motion.div>
          </>
        )}
      </AnimatePresence>
    </motion.div>
  );
}
